// msg.payload = texto do contagem.csv ('' se ainda nao existe)
// GET /api/dashboard?data=2026-10-14  (sem data = hoje)
// Devolve as laminas de cada esteira em cada hora do dia (00h a 23h)
function dataLocal(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

var hoje = dataLocal(new Date());
var pedida = msg.req && msg.req.query ? String(msg.req.query.data || '') : '';
var dia = /^\d{4}-\d{2}-\d{2}$/.test(pedida) ? pedida : hoje;

var texto = typeof msg.payload === 'string' ? msg.payload : '';
var linhas = texto.split(/\r?\n/);
var cabecalho = (linhas[0] || '').split(',');
var iEsteira = cabecalho.indexOf('esteira');
var iTimestamp = cabecalho.indexOf('timestamp');

var porEsteira = {}; // { esteira1: [24 numeros] }
var total = 0;

if (iEsteira !== -1 && iTimestamp !== -1) {
    for (var i = 1; i < linhas.length; i++) {
        if (!linhas[i].trim()) continue;
        var c = linhas[i].split(',');
        var momento = new Date(c[iTimestamp]);
        if (isNaN(momento.getTime())) continue;
        if (dataLocal(momento) !== dia) continue; // horario local do PC
        var esteira = c[iEsteira];
        if (!porEsteira[esteira]) porEsteira[esteira] = new Array(24).fill(0);
        porEsteira[esteira][momento.getHours()]++;
        total++;
    }
}

// para hoje, as horas que ainda nao chegaram ficam de fora do grafico
var ultimaHora = dia === hoje ? new Date().getHours() : 23;
if (dia > hoje) ultimaHora = -1;

msg.statusCode = 200;
msg.payload = { data: dia, ultima_hora: ultimaHora, total: total, por_hora: porEsteira };
return msg;

// So trata como vazio quando o arquivo nao existe.
var texto = (msg.error && msg.error.message) ? msg.error.message : '';
if (texto.indexOf('ENOENT') !== -1) {
    msg.payload = '';
    return [msg, null];
}
msg.statusCode = 500;
msg.payload = { erro: 'Nao foi possivel ler o contagem.csv (aberto no Excel?): ' + texto };
return [null, msg];

var texto = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
msg.statusCode = 500;
msg.payload = { erro: 'Falha no dashboard: ' + texto };
return msg;

// msg.payload = texto do paradas.csv ('' se ainda nao existe)
// GET /api/dashboard/manutencao?inicio=2026-10-01&fim=2026-10-15  (sem datas = todo o periodo)
// Soma o tempo parado de cada esteira DENTRO do periodo e conta os defeitos.
function inicioDoDia(texto) {
    var p = texto.split('-').map(Number);
    return new Date(p[0], p[1] - 1, p[2]); // 00:00 no horario local do PC
}
var q = (msg.req && msg.req.query) || {};
var formato = /^\d{4}-\d{2}-\d{2}$/;
var periodoInicio = formato.test(q.inicio || '') ? inicioDoDia(q.inicio) : null;
var periodoFim = null;
if (formato.test(q.fim || '')) {
    periodoFim = inicioDoDia(q.fim);
    periodoFim.setDate(periodoFim.getDate() + 1); // fim inclusivo: vai ate 23:59 do ultimo dia
}

var tempo = {};      // { esteira1: minutos }
var quantidade = {}; // { esteira1: numero de paradas }
var defeitos = {};   // { 'Serra sem fio': { esteira1: 2, esteira3: 1 } }
var totalMin = 0;
var totalParadas = 0;

var linhas = (typeof msg.payload === 'string' ? msg.payload : '').split(/\r?\n/);
for (var i = 1; i < linhas.length; i++) {
    if (!linhas[i].trim()) continue;
    var c = linhas[i].split(',');
    if (c.length < 4) continue;
    var esteira = c[0];
    var ini = new Date(c[1]);
    var fim = new Date(c[2]);
    if (isNaN(ini.getTime()) || isNaN(fim.getTime())) continue;

    // parte da parada que caiu dentro do periodo pedido
    var a = periodoInicio && ini < periodoInicio ? periodoInicio : ini;
    var b = periodoFim && fim > periodoFim ? periodoFim : fim;
    if (b <= a && !(ini.getTime() === fim.getTime() && (!periodoInicio || ini >= periodoInicio) && (!periodoFim || ini < periodoFim))) continue;

    var minutos = Math.max(0, Math.round((b - a) / 60000));
    tempo[esteira] = (tempo[esteira] || 0) + minutos;
    quantidade[esteira] = (quantidade[esteira] || 0) + 1;
    totalMin += minutos;
    totalParadas++;

    var defeito = (c[8] || '').trim() || 'Nao informado';
    if (!defeitos[defeito]) defeitos[defeito] = {};
    defeitos[defeito][esteira] = (defeitos[defeito][esteira] || 0) + 1;
}

msg.statusCode = 200;
msg.payload = {
    inicio: q.inicio || null,
    fim: q.fim || null,
    total_min: totalMin,
    total_paradas: totalParadas,
    tempo_parado_min: tempo,
    paradas_qtd: quantidade,
    defeitos: defeitos
};
return msg;

// So trata como vazio quando o arquivo nao existe.
var texto = (msg.error && msg.error.message) ? msg.error.message : '';
if (texto.indexOf('ENOENT') !== -1) {
    msg.payload = '';
    return [msg, null];
}
msg.statusCode = 500;
msg.payload = { erro: 'Nao foi possivel ler o contagem.csv (aberto no Excel?): ' + texto };
return [null, msg];

var texto = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
msg.statusCode = 500;
msg.payload = { erro: 'Falha no dashboard de manutencao: ' + texto };
return msg;

// msg.payload = texto do contagem.csv ('' se ainda nao existe)
// GET /api/analise?data=2026-10-21  (sem data = hoje)
// Prepara os dados para a pagina de Analise de Dados:
//   - tabela de frequencia da temperatura e da umidade de cada esteira
//     (quantas vezes cada valor apareceu -> o site calcula media, mediana e moda)
//   - laminas cortadas em cada hora
//   - quantas leituras chegaram (brutas) e quantas foram descartadas na limpeza
function dataLocal(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

var hoje = dataLocal(new Date());
var pedida = msg.req && msg.req.query ? String(msg.req.query.data || '') : '';
var dia = /^\d{4}-\d{2}-\d{2}$/.test(pedida) ? pedida : hoje;

var linhas = (typeof msg.payload === 'string' ? msg.payload : '').split(/\r?\n/);
var cabecalho = (linhas[0] || '').split(',');
var iEsteira = cabecalho.indexOf('esteira');
var iTimestamp = cabecalho.indexOf('timestamp');
var iTemp = cabecalho.indexOf('temperatura');
var iUmid = cabecalho.indexOf('umidade');

var esteiras = {};
function daEsteira(codigo) {
    if (!esteiras[codigo]) {
        esteiras[codigo] = {
            brutas: 0,
            descartadas: 0,
            temperatura: {},          // { "25.3": 12, ... }
            umidade: {},
            laminas_por_hora: new Array(24).fill(0)
        };
    }
    return esteiras[codigo];
}

// limpeza: valor vazio, nao numerico ou fora de uma faixa possivel e descartado
function valorValido(texto, minimo, maximo) {
    if (texto === undefined || String(texto).trim() === '') return null;
    var n = Number(texto);
    if (!isFinite(n) || n < minimo || n > maximo) return null;
    return Math.round(n * 10) / 10;
}

if (iEsteira !== -1 && iTimestamp !== -1) {
    for (var i = 1; i < linhas.length; i++) {
        if (!linhas[i].trim()) continue;
        var c = linhas[i].split(',');
        var momento = new Date(c[iTimestamp]);
        if (isNaN(momento.getTime()) || dataLocal(momento) !== dia) continue;

        var e = daEsteira(c[iEsteira]);
        e.brutas++;
        e.laminas_por_hora[momento.getHours()]++; // toda linha e uma lamina cortada

        var t = iTemp !== -1 ? valorValido(c[iTemp], -10, 80) : null;
        var u = iUmid !== -1 ? valorValido(c[iUmid], 0, 100) : null;
        if (t === null || u === null) {
            e.descartadas++;
            continue;
        }
        e.temperatura[t.toFixed(1)] = (e.temperatura[t.toFixed(1)] || 0) + 1;
        e.umidade[u.toFixed(1)] = (e.umidade[u.toFixed(1)] || 0) + 1;
    }
}

var ultimaHora = dia === hoje ? new Date().getHours() : 23;
if (dia > hoje) ultimaHora = -1;

msg.statusCode = 200;
msg.payload = { data: dia, ultima_hora: ultimaHora, esteiras: esteiras };
return msg;

// So trata como vazio quando o arquivo nao existe.
var texto = (msg.error && msg.error.message) ? msg.error.message : '';
if (texto.indexOf('ENOENT') !== -1) {
    msg.payload = '';
    return [msg, null];
}
msg.statusCode = 500;
msg.payload = { erro: 'Nao foi possivel ler o contagem.csv (aberto no Excel?): ' + texto };
return [null, msg];

var texto = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
msg.statusCode = 500;
msg.payload = { erro: 'Falha na analise de dados: ' + texto };
return msg;
